using BARANG.Core.Domain.Finance;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace BARANG.Core.Infrastructure.Persistence.Configurations;

internal static class FinanceConfiguration
{
    internal static void Base<T>(EntityTypeBuilder<T>b)where T:class{b.HasKey("Id");b.Property("Id").HasColumnName("id");b.Property("CompanyId").HasColumnName("company_id");}
    internal static void Money<T>(EntityTypeBuilder<T>b,string property,string column)where T:class=>b.Property<decimal>(property).HasColumnName(column).HasPrecision(18,2);
}
internal sealed class PaymentConfiguration:IEntityTypeConfiguration<Payment>
{
    public void Configure(EntityTypeBuilder<Payment>b){b.ToTable("payments",t=>t.HasCheckConstraint("ck_payments_amount","amount > 0"));FinanceConfiguration.Base(b);b.HasAlternateKey(x=>new{x.CompanyId,x.Id});b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.RecordType).HasColumnName("record_type").HasConversion<string>().HasMaxLength(16);b.Property(x=>x.PaymentMethodCode).HasColumnName("payment_method_code").HasMaxLength(100);FinanceConfiguration.Money(b,nameof(Payment.Amount),"amount");b.Property(x=>x.CurrencyCode).HasColumnName("currency_code").HasMaxLength(3).IsFixedLength();b.Property(x=>x.ReferenceNumber).HasColumnName("reference_number").HasMaxLength(150);b.Property(x=>x.PaidAtUtc).HasColumnName("paid_at_utc");b.Property(x=>x.RegisteredByUserId).HasColumnName("registered_by_user_id");b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(16);b.Property(x=>x.OriginalPaymentId).HasColumnName("original_payment_id");b.Property(x=>x.ReversalReason).HasColumnName("reversal_reason").HasMaxLength(500);b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.Version).HasColumnName("version");b.HasIndex(x=>new{x.CompanyId,x.OrderId,x.PaidAtUtc});b.HasIndex(x=>new{x.CompanyId,x.ReferenceNumber}).IsUnique().HasFilter("reference_number IS NOT NULL").HasDatabaseName("uq_payments_company_reference");b.HasOne<Domain.Orders.Order>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Payment>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OriginalPaymentId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}
}
internal sealed class OrderFinancialStateConfiguration:IEntityTypeConfiguration<OrderFinancialState>
{
    public void Configure(EntityTypeBuilder<OrderFinancialState>b){b.ToTable("order_financial_states");FinanceConfiguration.Base(b);b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(16);b.Property(x=>x.Reason).HasColumnName("reason").HasMaxLength(500);b.Property(x=>x.DecidedByUserId).HasColumnName("decided_by_user_id");b.Property(x=>x.DecidedAtUtc).HasColumnName("decided_at_utc");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.OrderId}).IsUnique();b.HasOne<Domain.Orders.Order>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}
}
internal sealed class InvoiceConfiguration:IEntityTypeConfiguration<Invoice>
{
    public void Configure(EntityTypeBuilder<Invoice>b){b.ToTable("invoices");FinanceConfiguration.Base(b);b.HasAlternateKey(x=>new{x.CompanyId,x.Id});b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.PriceSnapshotId).HasColumnName("price_snapshot_id");b.Property(x=>x.InvoiceNumber).HasColumnName("invoice_number").HasMaxLength(40);b.Property(x=>x.InvoiceType).HasColumnName("invoice_type").HasConversion<string>().HasMaxLength(16);b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(16);b.Property(x=>x.IssuedAtUtc).HasColumnName("issued_at_utc");b.Property(x=>x.CreatedByUserId).HasColumnName("created_by_user_id");b.Property(x=>x.Version).HasColumnName("version");b.HasIndex(x=>new{x.CompanyId,x.InvoiceNumber}).IsUnique();b.HasIndex(x=>new{x.CompanyId,x.OrderId,x.InvoiceType}).IsUnique();b.HasOne<Domain.Orders.Order>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Pricing.OrderPriceSnapshot>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.PriceSnapshotId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}
}
internal sealed class InvoiceSnapshotConfiguration:IEntityTypeConfiguration<InvoiceSnapshot>
{
    public void Configure(EntityTypeBuilder<InvoiceSnapshot>b){b.ToTable("invoice_snapshots");FinanceConfiguration.Base(b);b.Property(x=>x.InvoiceId).HasColumnName("invoice_id");b.Property(x=>x.OrderNumber).HasColumnName("order_number").HasMaxLength(40);b.Property(x=>x.CustomerCode).HasColumnName("customer_code").HasMaxLength(100);b.Property(x=>x.CustomerName).HasColumnName("customer_name").HasMaxLength(300);b.Property(x=>x.CurrencyCode).HasColumnName("currency_code").HasMaxLength(3).IsFixedLength();foreach(string p in new[]{nameof(InvoiceSnapshot.RawProductTotal),nameof(InvoiceSnapshot.PrintTotal),nameof(InvoiceSnapshot.AdditionalServiceTotal),nameof(InvoiceSnapshot.PackagingTotal),nameof(InvoiceSnapshot.ShippingTotal),nameof(InvoiceSnapshot.Subtotal),nameof(InvoiceSnapshot.DiscountTotal),nameof(InvoiceSnapshot.TaxTotal),nameof(InvoiceSnapshot.FinalTotal)})FinanceConfiguration.Money(b,p,System.Text.Json.JsonNamingPolicy.SnakeCaseLower.ConvertName(p));b.HasIndex(x=>new{x.CompanyId,x.InvoiceId}).IsUnique();b.HasOne<Invoice>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.InvoiceId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}
}
internal sealed class InvoiceItemSnapshotConfiguration:IEntityTypeConfiguration<InvoiceItemSnapshot>
{
    public void Configure(EntityTypeBuilder<InvoiceItemSnapshot>b){b.ToTable("invoice_item_snapshots");FinanceConfiguration.Base(b);b.Property(x=>x.InvoiceId).HasColumnName("invoice_id");b.Property(x=>x.OrderItemId).HasColumnName("order_item_id");b.Property(x=>x.LineNumber).HasColumnName("line_number");b.Property(x=>x.ProductCode).HasColumnName("product_code").HasMaxLength(100);b.Property(x=>x.ProductName).HasColumnName("product_name").HasMaxLength(300);b.Property(x=>x.VariantSku).HasColumnName("variant_sku").HasMaxLength(100);b.Property(x=>x.Quantity).HasColumnName("quantity").HasPrecision(18,4);FinanceConfiguration.Money(b,nameof(InvoiceItemSnapshot.Subtotal),"subtotal");FinanceConfiguration.Money(b,nameof(InvoiceItemSnapshot.Discount),"discount");FinanceConfiguration.Money(b,nameof(InvoiceItemSnapshot.Tax),"tax");FinanceConfiguration.Money(b,nameof(InvoiceItemSnapshot.FinalTotal),"final_total");b.HasIndex(x=>new{x.CompanyId,x.InvoiceId,x.LineNumber}).IsUnique();b.HasOne<Invoice>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.InvoiceId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}
}
internal sealed class FinanceHistoryConfiguration:IEntityTypeConfiguration<FinanceHistory>
{
    public void Configure(EntityTypeBuilder<FinanceHistory>b){b.ToTable("finance_history");FinanceConfiguration.Base(b);b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.EventType).HasColumnName("event_type").HasMaxLength(64);b.Property(x=>x.OccurredAtUtc).HasColumnName("occurred_at_utc");b.Property(x=>x.ActorUserId).HasColumnName("actor_user_id");b.Property(x=>x.RelatedEntityId).HasColumnName("related_entity_id");b.Property(x=>x.Summary).HasColumnName("summary").HasMaxLength(500);b.HasIndex(x=>new{x.CompanyId,x.OrderId,x.OccurredAtUtc,x.Id});b.HasOne<Domain.Orders.Order>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}
}
